import{_ as t,o,c as i,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Post-Deployment Verification Rules","description":"Guidelines for AI agents to independently verify that a CI/CD deployment was successful.","frontmatter":{"isInternal":true,"type":"Architecture Decision Record","title":"Post-Deployment Verification Rules","description":"Guidelines for AI agents to independently verify that a CI/CD deployment was successful.","tags":["deployment","verification","ci-cd","testing"]},"headers":[],"relativePath":"adr/2026-07-05-post-deployment-verification-rules.md","filePath":"adr/2026-07-05-post-deployment-verification-rules.md"}'),s={name:"adr/2026-07-05-post-deployment-verification-rules.md"};function n(r,e,c,l,d,u){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="post-deployment-verification-rules" tabindex="-1">Post-Deployment Verification Rules <a class="header-anchor" href="#post-deployment-verification-rules" aria-label="Permalink to &quot;Post-Deployment Verification Rules&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>When a branch is merged (e.g., <code>dev</code> into <code>staging</code>, or <code>staging</code> into <code>main</code>), GitHub Actions automatically triggers a deployment pipeline. However, simply pushing the code is not enough to consider the task &quot;done&quot;. The deployment might fail due to syntax errors, build failures, or misconfigured secrets.</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>If an agent merges code and immediately concludes the task without verifying the deployment, the user may discover a broken environment minutes later. Agents must &quot;close the loop&quot; on deployments.</p><h2 id="solution" tabindex="-1">Solution <a class="header-anchor" href="#solution" aria-label="Permalink to &quot;Solution&quot;">​</a></h2><p>After pushing code that triggers a deployment, agents <strong>MUST</strong> explicitly verify the deployment success before concluding their turn.</p><h3 id="verification-steps" tabindex="-1">Verification Steps <a class="header-anchor" href="#verification-steps" aria-label="Permalink to &quot;Verification Steps&quot;">​</a></h3><ol><li><p><strong>Track the CI/CD Pipeline:</strong> Agents must check the status of the GitHub Action that was triggered by the push.</p><ul><li>If the <code>gh</code> CLI tool is available, use <code>gh run list --limit 1</code> or <code>gh run watch</code>.</li><li>If <code>gh</code> is unavailable, use the GitHub REST API: <code>curl -s &quot;https://api.github.com/repos/&lt;owner&gt;/&lt;repo&gt;/actions/runs?per_page=1&quot;</code>.</li><li>Wait until the action <code>status</code> is <code>completed</code> and verify the <code>conclusion</code> is <code>success</code>.</li></ul></li><li><p><strong>Verify the Live Environment:</strong> Once the pipeline succeeds, agents must verify that the target environment actually reflects the new deployment.</p><ul><li>Run a basic HTTP check against the deployment URL (e.g., <code>curl -I https://sanjeev-ai-staging.web.app</code>).</li><li>Check headers like <code>Last-Modified</code> or <code>Date</code> to confirm the site was updated recently, or look for specific changes in the payload if applicable.</li></ul></li></ol><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Never assume a deployment succeeded just because the <code>git push</code> succeeded. The CI/CD pipeline is asynchronous. You must wait for it to finish and report the final status to the user.</p></div>',10)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
